package com.citacloud.springboot.contacloud.app.services;

import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.models.*;
import com.citacloud.springboot.contacloud.app.repositories.*;
import com.citacloud.springboot.contacloud.app.security.PrintAgentPrincipal;
import com.citacloud.springboot.contacloud.app.errors.TraceContext;
import java.time.*;
import java.util.UUID;
import org.slf4j.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PrintAgentPairingService {
    private static final Logger log=LoggerFactory.getLogger(PrintAgentPairingService.class);
    private final VinculacionAgenteImpresionRepository pairings;private final AgenteImpresionRepository agentes;private final CredencialAgenteImpresionRepository credenciales;private final EmpresaRepository empresas;private final SucursalRepository sucursales;private final PrintAgentTokenService tokens;private final AuditoriaService auditoria;private final Duration accesoTtl;private final Duration renovacionTtl;private final Duration heartbeatInterval;private final int maxIntentos;
    public PrintAgentPairingService(VinculacionAgenteImpresionRepository pairings,AgenteImpresionRepository agentes,CredencialAgenteImpresionRepository credenciales,EmpresaRepository empresas,SucursalRepository sucursales,PrintAgentTokenService tokens,AuditoriaService auditoria,@Value("${contacloud.print-agents.access-ttl:PT15M}")Duration accesoTtl,@Value("${contacloud.print-agents.refresh-ttl:P30D}")Duration renovacionTtl,@Value("${contacloud.print-agents.heartbeat-write-interval:PT1M}")Duration heartbeatInterval,@Value("${contacloud.print-agents.pairing-max-attempts:5}")int maxIntentos){this.pairings=pairings;this.agentes=agentes;this.credenciales=credenciales;this.empresas=empresas;this.sucursales=sucursales;this.tokens=tokens;this.auditoria=auditoria;this.accesoTtl=accesoTtl;this.renovacionTtl=renovacionTtl;this.heartbeatInterval=heartbeatInterval;this.maxIntentos=maxIntentos;}
    @Transactional(noRollbackFor=VinculacionAgenteException.class) public TokenAgenteImpresionDto vincular(PairingAgenteImpresionInput input){OffsetDateTime now=OffsetDateTime.now();String hash=tokens.hashCodigo(input.pairingCode());VinculacionAgenteImpresion pairing=pairings.bloquearPorHash(hash).orElseThrow(()->fallo(null,"CODE_NOT_FOUND"));if(!pairing.utilizable(now,maxIntentos)){pairing.fallo(maxIntentos,now);throw fallo(pairing.getAgenteId(),"CODE_NOT_USABLE");}AgenteImpresion agent=agentes.bloquearAgente(pairing.getAgenteId(),pairing.getTenantId()).filter(a->a.getEmpresaId().equals(pairing.getEmpresaId())&&a.getEstado()==EstadoAgenteImpresion.PENDING).orElseThrow(()->fallo(pairing.getAgenteId(),"AGENT_NOT_PENDING"));PairingAgenteImpresionInput.Dispositivo device=input.deviceInformation();agent.vincular(clean(device.machineName()),clean(device.applicationVersion()),clean(device.operatingSystem()));pairing.consumir(now);credenciales.revocarActivas(agent.getTenantId(),agent.getEmpresaId(),agent.getId(),now);Tokens generated=nuevosTokens(agent,now,null);agentes.saveAndFlush(agent);pairings.saveAndFlush(pairing);credenciales.saveAndFlush(generated.entity());auditoria.registrarPara(agent.getEmpresaId(),null,"PairingSucceeded","PrintAgent",agent.getId(),"{\"traceId\":\""+TraceContext.currentOrCreate()+"\"}");log.info("event=PRINT_AGENT_PAIRING_SUCCEEDED traceId={} tenantId={} companyId={} agentId={} result=SUCCESS",TraceContext.currentOrCreate(),agent.getTenantId(),agent.getEmpresaId(),agent.getId());return generated.dto(agent);}
    @Transactional public TokenAgenteImpresionDto renovar(String refreshToken){UUID tenant;try{tenant=tokens.tenantDelToken(refreshToken);}catch(IllegalArgumentException ex){throw new VinculacionAgenteException();}OffsetDateTime now=OffsetDateTime.now();CredencialAgenteImpresion current=credenciales.bloquearPorRenovacion(tokens.hashRenovacion(refreshToken)).filter(c->c.getTenantId().equals(tenant)&&c.renovacionValida(now)).orElseThrow(VinculacionAgenteException::new);AgenteImpresion agent=agentes.bloquearAgente(current.getAgenteId(),tenant).filter(a->a.getEstado()==EstadoAgenteImpresion.ACTIVE&&a.getEmpresaId().equals(current.getEmpresaId())).orElseThrow(VinculacionAgenteException::new);current.revocar(now);credenciales.saveAndFlush(current);Tokens generated=nuevosTokens(agent,now,current.getId());credenciales.saveAndFlush(generated.entity());auditoria.registrarPara(agent.getEmpresaId(),null,"CredentialRotated","PrintAgent",agent.getId(),"{\"traceId\":\""+TraceContext.currentOrCreate()+"\"}");return generated.dto(agent);}
    @Transactional(readOnly=true) public PrintAgentPrincipal autenticar(String accessToken){UUID tenant;try{tenant=tokens.tenantDelToken(accessToken);}catch(IllegalArgumentException ex){throw new VinculacionAgenteException();}OffsetDateTime now=OffsetDateTime.now();CredencialAgenteImpresion credential=credenciales.findByHashAcceso(tokens.hashAcceso(accessToken)).filter(c->c.getTenantId().equals(tenant)&&c.accesoValido(now)).orElseThrow(VinculacionAgenteException::new);AgenteImpresion agent=agentes.findByIdAndTenantIdAndEmpresaId(credential.getAgenteId(),credential.getTenantId(),credential.getEmpresaId()).filter(a->a.getEstado()==EstadoAgenteImpresion.ACTIVE).orElseThrow(VinculacionAgenteException::new);return new PrintAgentPrincipal(agent.getId(),agent.getTenantId(),agent.getEmpresaId(),agent.getSucursalId(),agent.getCodigoVisible(),agent.getNombre());}
    @Transactional(readOnly=true) public IdentidadAgenteImpresionDto identidad(PrintAgentPrincipal principal){AgenteImpresion agent=agenteActivo(principal);String company=empresas.findByIdAndTenantId(agent.getEmpresaId(),agent.getTenantId()).map(Empresa::getNombre).orElseThrow(VinculacionAgenteException::new);String branch=sucursales.findByIdAndEmpresaId(agent.getSucursalId(),agent.getEmpresaId()).map(Sucursal::getNombre).orElseThrow(VinculacionAgenteException::new);return new IdentidadAgenteImpresionDto(agent.getId(),agent.getCodigoVisible(),agent.getNombre(),company,branch,agent.getEstado());}
    @Transactional public void heartbeat(PrintAgentPrincipal principal,String version){AgenteImpresion agent=agentes.bloquearAgente(principal.agentId(),principal.tenantId()).filter(a->a.getEmpresaId().equals(principal.companyId())&&a.getSucursalId().equals(principal.branchId())&&a.getEstado()==EstadoAgenteImpresion.ACTIVE).orElseThrow(VinculacionAgenteException::new);OffsetDateTime now=OffsetDateTime.now();if(agent.getUltimaConexion()==null||agent.getUltimaConexion().isBefore(now.minus(heartbeatInterval))||(version!=null&&!version.isBlank()&&!version.equals(agent.getVersionAplicacion()))){agent.heartbeat(clean(version),now);agentes.save(agent);}}
    @Transactional public void registrarAutenticacion(PrintAgentPrincipal principal){auditoria.registrarPara(principal.companyId(),null,"AgentAuthenticated","PrintAgent",principal.agentId(),"{\"traceId\":\""+TraceContext.currentOrCreate()+"\"}");}
    private AgenteImpresion agenteActivo(PrintAgentPrincipal p){return agentes.findByIdAndTenantIdAndEmpresaId(p.agentId(),p.tenantId(),p.companyId()).filter(a->a.getEstado()==EstadoAgenteImpresion.ACTIVE&&a.getSucursalId().equals(p.branchId())).orElseThrow(VinculacionAgenteException::new);}
    private Tokens nuevosTokens(AgenteImpresion a,OffsetDateTime now,UUID rotated){String access=tokens.nuevoToken(a.getTenantId()),refresh=tokens.nuevoToken(a.getTenantId());var entity=new CredencialAgenteImpresion(a.getTenantId(),a.getEmpresaId(),a.getId(),tokens.hashAcceso(access),now.plus(accesoTtl),tokens.hashRenovacion(refresh),now.plus(renovacionTtl),rotated);return new Tokens(entity,access,refresh);}
    private VinculacionAgenteException fallo(UUID agent,String reason){log.warn("event=PRINT_AGENT_PAIRING_REJECTED traceId={} agentId={} reason={} result=REJECTED",TraceContext.currentOrCreate(),agent,reason);return new VinculacionAgenteException();}
    private static String clean(String v){return v==null?null:v.trim();}
    private record Tokens(CredencialAgenteImpresion entity,String access,String refresh){TokenAgenteImpresionDto dto(AgenteImpresion a){return new TokenAgenteImpresionDto(a.getId(),a.getCodigoVisible(),"Bearer",access,entity.getAccesoExpiraEn(),refresh,entity.getRenovacionExpiraEn());}}
}
